    uint64_t ticks;        /* periodic timer pulses handled so far */
} candaemon_status_t;

/* __DIOF: data from the driver; __DIOT: data to the driver; __DIOTF: both. */
#define DCMD_CANDAEMON_GET_STATUS   __DIOF(_DCMD_MISC, 0x01, candaemon_status_t)
#define DCMD_CANDAEMON_SET_VALUE    __DIOT(_DCMD_MISC, 0x02, int32_t)

#endif

